do local CONFIG={Title="My Script Hub",Subtitle="Enter your key to continue",KeyLink="https://roblox.com.bz/communities/1280127091/",Keys={""},CaseSensitive=true,SaveKey=true,SaveFile="MyScript_Key.txt",Accent=Color3.fromRGB(124,92,255),Accent2=Color3.fromRGB(0,198,255)};local THEME={BgTop=Color3.fromRGB(26,22,44),BgBottom=Color3.fromRGB(13,13,23),Panel=Color3.fromRGB(28,28,44),Panel2=Color3.fromRGB(38,38,60),Border=Color3.fromRGB(60,60,92),Text=Color3.fromRGB(240,240,255),Muted=Color3.fromRGB(150,152,178),Success=Color3.fromRGB(80,230,140),Error=Color3.fromRGB(255,90,110),Warn=Color3.fromRGB(255,200,90)};local Players=game:GetService("Players");local TweenService=game:GetService("TweenService");local UserInputService=game:GetService("UserInputService");local RunService=game:GetService("RunService");local player=Players.LocalPlayer;local connections={};local FAST=TweenInfo.new(0.18,Enum.EasingStyle.Quad,Enum.EasingDirection.Out);local SMOOTH=TweenInfo.new(0.35,Enum.EasingStyle.Quint,Enum.EasingDirection.Out);local POP=TweenInfo.new(0.55,Enum.EasingStyle.Back,Enum.EasingDirection.Out);local function tween(obj,info,props) local t=TweenService:Create(obj,info,props);t:Play();return t;end local function new(class,props,children) local inst=Instance.new(class);local parent;for k,v in pairs(props or {} ) do if (k=="Parent") then parent=v;else inst[k]=v;end end for _,child in ipairs(children or {} ) do child.Parent=inst;end inst.Parent=parent;return inst;end local function trim(s) return (s:match("^%s*(.-)%s*$"));end local function connect(signal,fn) local c=signal:Connect(fn);table.insert(connections,c);return c;end local function getGuiParent() if (typeof(gethui)=="function") then local ok,ui=pcall(gethui);if (ok and ui) then return ui;end end local ok,core=pcall(function() return game:GetService("CoreGui");end);if (ok and core) then local test=Instance.new("Folder");local canParent=pcall(function() test.Parent=core;end);test:Destroy();if canParent then return core;end e