l});else border=new("UIStroke",{Color=CONFIG.Accent,Thickness=1.5,Transparency=0.45,ApplyStrokeMode=Enum.ApplyStrokeMode.Border,Parent=fill});end local label=new("TextLabel",{Name="Label",Size=UDim2.fromScale(1,1),BackgroundTransparency=1,Text=text,TextColor3=THEME.Text,Font=Enum.Font.GothamBold,TextSize=15,ZIndex=3,Parent=btn});local scale=new("UIScale",{Scale=1,Parent=btn});btn.MouseEnter:Connect(function() tween(scale,FAST,{Scale=1.03});if  not filled then tween(fill,FAST,{BackgroundColor3=Color3.fromRGB(50,50,78)});tween(border,FAST,{Transparency=0});end end);btn.MouseLeave:Connect(function() tween(scale,FAST,{Scale=1});if  not filled then tween(fill,FAST,{BackgroundColor3=THEME.Panel2});tween(border,FAST,{Transparency=0.45});end end);btn.MouseButton1Down:Connect(function() tween(scale,TweenInfo.new(0.08),{Scale=0.96});end);btn.MouseButton1Up:Connect(function() tween(scale,FAST,{Scale=1.03});end);return btn,label;end local checkBtn,checkLabel=makeButton("CheckKey","Check Key",UDim2.new(0,0,0,0),true);local copyBtn,copyLabel=makeButton("CopyLink","Copy Link",UDim2.new(0.5,6,0,0),false);new("TextLabel",{Name="Footer",Position=UDim2.fromOffset(24,246),Size=UDim2.new(1, -48,0,24),BackgroundTransparency=1,Text="Need a key? Hit Copy Link, open it in your browser and paste the key above.",TextColor3=THEME.Muted,TextTransparency=0.25,TextWrapped=true,Font=Enum.Font.Gotham,TextSize=11,ZIndex=2,Parent=main});local busy,accepted,closed=false,false,false;local function setStatus(text,color) status.Text=text;tween(status,FAST,{TextColor3=color or THEME.Muted });end local function setBorder(color) tween(inputBorder,FAST,{Color=color});end local function shake() task.spawn(function() local origin=holder.Position;for _,dx in ipairs({ -10,10, -7,7, -3,3,0}) do local t=tween(holder,TweenInfo.new(0.04),{Position=UDim2.new(origin.X.Scale,origin.X.Offset + dx ,origin.Y.Scale,origin.Y.Offset)});t.Completed:Wait();end end);end local function closeGui(runMain) if closed then return;end